sed -i '/useEffect(() => {/,/}, \[userEmail\]);/c\  useEffect(() => {\n    if (!userEmail) return;\n    const fetchData = async () => {\n      try {\n        const [paymentsRes, notesRes] = await Promise.all([\n          fetch(`/api/users/${encodeURIComponent(userEmail)}/payments`),\n          fetch(`/api/users/${encodeURIComponent(userEmail)}/notes`)\n        ]);\n        if (!paymentsRes.ok || !notesRes.ok) throw new Error("Failed to fetch dashboard data");\n        const paymentsData = await paymentsRes.json();\n        const notesData = await notesRes.json();\n        setPayments(paymentsData.payments || []);\n        setNotes(notesData.notes || []);\n      } catch (err: any) {\n        console.error("Error fetching data:", err);\n        setError(err.message || "Failed to load dashboard data");\n      } finally {\n        setLoading(false);\n      }\n    };\n    fetchData();\n  }, [userEmail]);' src/pages/DashboardPage.tsx
